//! A built-in synthesized drum kit: kick, snare, clap, closed/open hi-hat, and
//! tom — all generated by Dhun's own DSP, no samples (SPEC §3.2).
//!
//! Each voice reseeds its noise from a fixed per-drum seed on trigger, so a
//! given pattern renders bit-identically every time (SPEC §5). Voices are
//! pre-allocated; `trigger`/`tick` never allocate.

use crate::filter::SvfLowpass;
use crate::oscillator::{Oscillator, Waveform};
use crate::util::NoiseRng;

/// Which drum voice to trigger.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DrumType {
    /// Bass drum.
    Kick,
    /// Snare drum.
    Snare,
    /// Hand clap.
    Clap,
    /// Closed hi-hat.
    ClosedHat,
    /// Open hi-hat.
    OpenHat,
    /// Tom.
    Tom,
}

/// Level below which an exponential decay counts as finished.
const SILENCE: f32 = 1e-4;

/// A one-pole-ish exponential decay from 1.0 toward 0.0, reaching ~e⁻⁵ of its
/// peak after `time_s`.
#[derive(Debug, Clone)]
struct ExpEnv {
    level: f32,
    coef: f32,
}

impl ExpEnv {
    fn new(sample_rate: f32, time_s: f32) -> Self {
        Self {
            level: 0.0,
            coef: (-5.0 / (time_s * sample_rate)).exp(),
        }
    }

    fn trigger(&mut self) {
        self.level = 1.0;
    }

    fn is_active(&self) -> bool {
        self.level > SILENCE
    }

    fn tick(&mut self) -> f32 {
        let v = self.level;
        self.level *= self.coef;
        v
    }
}

/// Kick / tom: a sine with a downward pitch sweep and an amplitude decay.
#[derive(Debug, Clone)]
struct PitchedDrum {
    osc: Oscillator,
    amp: ExpEnv,
    pitch: ExpEnv,
    f_start: f32,
    f_end: f32,
    velocity: f32,
}

impl PitchedDrum {
    fn new(sample_rate: f32, f_start: f32, f_end: f32, amp_time: f32, pitch_time: f32) -> Self {
        Self {
            osc: Oscillator::new(sample_rate, Waveform::Sine),
            amp: ExpEnv::new(sample_rate, amp_time),
            pitch: ExpEnv::new(sample_rate, pitch_time),
            f_start,
            f_end,
            velocity: 0.0,
        }
    }

    fn trigger(&mut self, velocity: f32) {
        self.osc.reset();
        self.amp.trigger();
        self.pitch.trigger();
        self.velocity = velocity;
    }

    fn is_active(&self) -> bool {
        self.amp.is_active()
    }

    fn tick(&mut self) -> f32 {
        if !self.is_active() {
            return 0.0;
        }
        let p = self.pitch.tick();
        self.osc
            .set_freq(self.f_end + (self.f_start - self.f_end) * p);
        self.osc.tick() * self.amp.tick() * self.velocity
    }
}

/// Snare: a tonal body plus a noise burst.
#[derive(Debug, Clone)]
struct Snare {
    body: Oscillator,
    body_amp: ExpEnv,
    noise: NoiseRng,
    noise_amp: ExpEnv,
    seed: u32,
    velocity: f32,
}

impl Snare {
    fn new(sample_rate: f32) -> Self {
        let mut body = Oscillator::new(sample_rate, Waveform::Sine);
        body.set_freq(180.0);
        Self {
            body,
            body_amp: ExpEnv::new(sample_rate, 0.12),
            noise: NoiseRng::new(0x5EED_05A1),
            noise_amp: ExpEnv::new(sample_rate, 0.2),
            seed: 0x5EED_05A1,
            velocity: 0.0,
        }
    }

    fn trigger(&mut self, velocity: f32) {
        self.body.reset();
        self.body_amp.trigger();
        self.noise = NoiseRng::new(self.seed);
        self.noise_amp.trigger();
        self.velocity = velocity;
    }

    fn is_active(&self) -> bool {
        self.body_amp.is_active() || self.noise_amp.is_active()
    }

    fn tick(&mut self) -> f32 {
        if !self.is_active() {
            return 0.0;
        }
        let body = self.body.tick() * self.body_amp.tick();
        let noise = self.noise.next_bipolar() * self.noise_amp.tick();
        (0.5 * body + 0.7 * noise) * self.velocity
    }
}

/// Clap: a short band of low-passed noise.
#[derive(Debug, Clone)]
struct Clap {
    noise: NoiseRng,
    seed: u32,
    lp: SvfLowpass,
    amp: ExpEnv,
    velocity: f32,
}

impl Clap {
    fn new(sample_rate: f32) -> Self {
        Self {
            noise: NoiseRng::new(0xC1A9),
            seed: 0xC1A9,
            lp: SvfLowpass::new(sample_rate, 2_500.0, 0.707),
            amp: ExpEnv::new(sample_rate, 0.18),
            velocity: 0.0,
        }
    }

    fn trigger(&mut self, velocity: f32) {
        self.noise = NoiseRng::new(self.seed);
        self.lp.reset();
        self.amp.trigger();
        self.velocity = velocity;
    }

    fn is_active(&self) -> bool {
        self.amp.is_active()
    }

    fn tick(&mut self) -> f32 {
        if !self.is_active() {
            return 0.0;
        }
        let x = self.noise.next_bipolar();
        self.lp.tick(x) * self.amp.tick() * self.velocity
    }
}

/// Hi-hat (closed or open): high-passed noise with a decay.
#[derive(Debug, Clone)]
struct Hat {
    noise: NoiseRng,
    seed: u32,
    lp: SvfLowpass,
    amp: ExpEnv,
    velocity: f32,
}

impl Hat {
    fn new(sample_rate: f32, decay: f32, seed: u32) -> Self {
        Self {
            noise: NoiseRng::new(seed),
            seed,
            lp: SvfLowpass::new(sample_rate, 6_000.0, 0.707),
            amp: ExpEnv::new(sample_rate, decay),
            velocity: 0.0,
        }
    }

    fn trigger(&mut self, velocity: f32) {
        self.noise = NoiseRng::new(self.seed);
        self.lp.reset();
        self.amp.trigger();
        self.velocity = velocity;
    }

    fn is_active(&self) -> bool {
        self.amp.is_active()
    }

    fn tick(&mut self) -> f32 {
        if !self.is_active() {
            return 0.0;
        }
        let x = self.noise.next_bipolar();
        let low = self.lp.tick(x);
        let high = x - low; // crude high-pass for a bright hat
        high * self.amp.tick() * self.velocity
    }
}

/// The full drum kit: one voice per drum, summed at the output.
#[derive(Debug, Clone)]
pub struct DrumKit {
    kick: PitchedDrum,
    tom: PitchedDrum,
    snare: Snare,
    clap: Clap,
    closed: Hat,
    open: Hat,
}

impl DrumKit {
    /// Creates a drum kit with all voices pre-allocated.
    #[must_use]
    pub fn new(sample_rate: f32) -> Self {
        Self {
            kick: PitchedDrum::new(sample_rate, 150.0, 50.0, 0.3, 0.06),
            tom: PitchedDrum::new(sample_rate, 160.0, 100.0, 0.4, 0.1),
            snare: Snare::new(sample_rate),
            clap: Clap::new(sample_rate),
            closed: Hat::new(sample_rate, 0.04, 0x00C1_05ED),
            open: Hat::new(sample_rate, 0.3, 0x09E2),
        }
    }

    /// Triggers a drum with the given linear velocity in `[0.0, 1.0]`.
    pub fn trigger(&mut self, drum: DrumType, velocity: f32) {
        match drum {
            DrumType::Kick => self.kick.trigger(velocity),
            DrumType::Snare => self.snare.trigger(velocity),
            DrumType::Clap => self.clap.trigger(velocity),
            DrumType::ClosedHat => self.closed.trigger(velocity),
            DrumType::OpenHat => self.open.trigger(velocity),
            DrumType::Tom => self.tom.trigger(velocity),
        }
    }

    /// Whether any voice is still sounding.
    #[must_use]
    pub fn is_active(&self) -> bool {
        self.kick.is_active()
            || self.tom.is_active()
            || self.snare.is_active()
            || self.clap.is_active()
            || self.closed.is_active()
            || self.open.is_active()
    }

    /// Advances one sample, summing all voices.
    pub fn tick(&mut self) -> f32 {
        self.kick.tick()
            + self.tom.tick()
            + self.snare.tick()
            + self.clap.tick()
            + self.closed.tick()
            + self.open.tick()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SR: f32 = 48_000.0;
    const ALL: [DrumType; 6] = [
        DrumType::Kick,
        DrumType::Snare,
        DrumType::Clap,
        DrumType::ClosedHat,
        DrumType::OpenHat,
        DrumType::Tom,
    ];

    #[test]
    fn each_drum_sounds_then_decays_to_silence() {
        for drum in ALL {
            let mut kit = DrumKit::new(SR);
            kit.trigger(drum, 1.0);
            let mut peak = 0.0f32;
            // 2 s is well past every voice's decay time.
            for _ in 0..(2 * SR as usize) {
                let s = kit.tick();
                assert!(s.is_finite(), "{drum:?} produced non-finite sample");
                peak = peak.max(s.abs());
            }
            assert!(peak > 0.01, "{drum:?} was essentially silent (peak {peak})");
            assert!(!kit.is_active(), "{drum:?} never finished decaying");
            assert_eq!(kit.tick(), 0.0, "{drum:?} not silent after decay");
        }
    }

    #[test]
    fn renders_are_deterministic() {
        for drum in ALL {
            let mut a = DrumKit::new(SR);
            let mut b = DrumKit::new(SR);
            a.trigger(drum, 0.9);
            b.trigger(drum, 0.9);
            for i in 0..20_000 {
                assert_eq!(a.tick(), b.tick(), "{drum:?} diverged at sample {i}");
            }
        }
    }

    #[test]
    fn full_kit_hit_is_bounded_and_finite() {
        let mut kit = DrumKit::new(SR);
        for drum in ALL {
            kit.trigger(drum, 1.0);
        }
        for _ in 0..(SR as usize) {
            let s = kit.tick();
            assert!(s.is_finite());
            assert!(s.abs() <= 6.0, "full-kit output {s} out of bounds");
        }
    }
}
